import { useState } from 'react'

// PDFs and page previews are generated by cv/build-pdf.sh into public/cv/.
// Update `pages` if the CV grows beyond two pages.
const BASE = `${import.meta.env.BASE_URL}cv/`
const FILES = {
  de: { label: 'Deutsch', name: 'Ismail_Cimen_CV_DE', pages: 2 },
  en: { label: 'English', name: 'Ismail_Cimen_CV_EN', pages: 2 },
} as const
type L = keyof typeof FILES

export default function CvViewer({ initial = 'de' }: { initial?: L }) {
  const [lang, setLang] = useState<L>(initial)
  const f = FILES[lang]
  const pdf = `${BASE}${f.name}.pdf`
  return (
    <div className="min-h-screen bg-ink font-sans text-paper">
      <header className="sticky top-0 z-50 border-b border-hair bg-ink/85 backdrop-blur-md">
        <div className="mx-auto flex max-w-6xl flex-wrap items-center justify-between gap-4 px-6 py-4">
          <a href="#top" className="label text-paper-dim transition-colors hover:text-paper">
            ← Website
          </a>
          <div className="flex items-center rounded-full border border-hair p-0.5">
            {(Object.keys(FILES) as L[]).map((k) => (
              <button
                key={k}
                onClick={() => setLang(k)}
                aria-pressed={lang === k}
                className={`label rounded-full px-3 py-1.5 transition-colors ${
                  lang === k ? 'bg-paper text-ink' : 'text-paper-dim hover:text-paper'
                }`}
              >
                {k.toUpperCase()}
              </button>
            ))}
          </div>
          <div className="flex items-center gap-3">
            <a href={pdf} target="_blank" rel="noreferrer" className="label rounded-full border border-hair px-4 py-2 hover:border-paper">
              Open
            </a>
            <a href={pdf} download className="label rounded-full bg-signal px-4 py-2 text-ink transition-transform hover:-translate-y-0.5">
              Download PDF
            </a>
          </div>
        </div>
      </header>
      <main className="mx-auto max-w-6xl px-6 py-10">
        <p className="label mb-2 text-paper-dim">CV · {f.pages} × A4 · {f.label}</p>
        <h1 className="mb-8 font-display text-4xl tracking-tight">İsmail Çimen — Lebenslauf / CV</h1>
        <div className="mx-auto max-w-3xl space-y-6">
          {Array.from({ length: f.pages }, (_, i) => (
            <img
              key={`${f.name}-${i}`}
              src={`${BASE}${f.name}-${i + 1}.png`}
              alt={`CV ${f.label}, page ${i + 1} of ${f.pages}`}
              className="w-full rounded-sm shadow-2xl shadow-black/40"
            />
          ))}
        </div>
      </main>
    </div>
  )
}
